public class FilenameUtils_getSanitizedEmbeddedFileName_3_0_Test {

    private FilenameUtils filenameUtils;

    private Metadata metadata;

    private Property property;

    @BeforeEach
    public void setUp() {
        filenameUtils = Mockito.spy(new FilenameUtils());
        metadata = Mockito.mock(Metadata.class);
        property = Mockito.mock(Property.class);
    }

    @Test
    public void testGetSanitizedEmbeddedFileName_withValidPath() throws Exception {
        when(metadata.get(any(Property.class))).thenReturn("example.txt");
        when(metadata.get(org.apache.tika.metadata.TikaCoreProperties.EMBEDDED_NAME)).thenReturn("example.txt");
        String result = filenameUtils.getSanitizedEmbeddedFileName(metadata, "txt", 100);
        String expected = "example.txt";
        assertEquals(expected, result);
    }

    @Test
    public void testGetSanitizedEmbeddedFileName_withEmptyPath() throws Exception {
        when(metadata.get(any(Property.class))).thenReturn("");
        when(metadata.get(org.apache.tika.metadata.TikaCoreProperties.EMBEDDED_NAME)).thenReturn("");
        String result = filenameUtils.getSanitizedEmbeddedFileName(metadata, "txt", 100);
        String expected = null;
        assertEquals(expected, result);
    }

    @Test
    public void testGetSanitizedEmbeddedFileName_withNullPath() throws Exception {
        when(metadata.get(any(Property.class))).thenReturn(null);
        when(metadata.get(org.apache.tika.metadata.TikaCoreProperties.EMBEDDED_NAME)).thenReturn(null);
        String result = filenameUtils.getSanitizedEmbeddedFileName(metadata, "txt", 100);
        String expected = null;
        assertEquals(expected, result);
    }

    @Test
    public void testGetSanitizedEmbeddedFileName_withLeadingDot() throws Exception {
        when(metadata.get(any(Property.class))).thenReturn(".example.txt");
        when(metadata.get(org.apache.tika.metadata.TikaCoreProperties.EMBEDDED_NAME)).thenReturn(".example.txt");
        String result = filenameUtils.getSanitizedEmbeddedFileName(metadata, "txt", 100);
        String expected = "example.txt";
        assertEquals(expected, result);
    }

    @Test
    public void testGetSanitizedEmbeddedFileName_withLongPath() throws Exception {
        when(metadata.get(any(Property.class))).thenReturn("aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa.txt");
        when(metadata.get(org.apache.tika.metadata.TikaCoreProperties.EMBEDDED_NAME)).thenReturn("aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa.txt");
        String result = filenameUtils.getSanitizedEmbeddedFileName(metadata, "txt", 100);
        String expected = "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa...txt";
        assertEquals(expected, result);
    }

    @Test
