    @Test
    public void testGetSanitizedEmbeddedFileName_withReservedCharacters() throws Exception {
        when(metadata.get(any(Property.class))).thenReturn("example<txt");
        when(metadata.get(org.apache.tika.metadata.TikaCoreProperties.EMBEDDED_NAME)).thenReturn("example<txt");
        String result = filenameUtils.getSanitizedEmbeddedFileName(metadata, "txt", 100);
        String expected = "example_txt";
        assertEquals(expected, result);
    }

    @Test
    public void testGetSanitizedEmbeddedFileName_withNullExtension() throws Exception {
        when(metadata.get(any(Property.class))).thenReturn("example");
